//! A native Wayland server: the listening socket, clients, object maps,
//! request dispatch, event marshalling, the registry and an epoll loop,
//! replacing libwayland-server.
//!
//! Typed bindings generated by tools/wayland-zig.zig --server wrap `Resource`
//! with one `send` method per event and a `Request` union per interface.
//! As with libwayland, descriptors passed in events are duplicated, so callers
//! keep theirs; descriptors received in requests belong to the handler.
const std = @import("std");
const linux = std.os.linux;
const wire = @import("wayland-wire");

pub const Fd = wire.Fd;
pub const Interface = wire.Interface;
pub const Message = wire.Message;
pub const NewId = wire.NewId;
pub const new_id = wire.new_id;
const max_message = wire.max_message;
const max_fds = wire.max_fds;
const server_base = wire.server_base;
/// A client whose unsent events exceed this is disconnected, as libwayland does when its buffer fills.
const max_pending = 4 << 20;

pub const Error = wire.Error || error{Disconnected};

/// wl_display error codes.
pub const DisplayError = struct {
    pub const invalid_object: u32 = 0;
    pub const invalid_method: u32 = 1;
    pub const no_memory: u32 = 2;
    pub const implementation: u32 = 3;
};

const Handler = *const fn (data: ?*anyopaque, request: *Request) void;
const Destructor = *const fn (data: ?*anyopaque, resource: Resource) void;

const Object = struct {
    interface: *const Interface,
    version: u32,
    data: ?*anyopaque = null,
    handler: ?Handler = null,
    destructor: ?Destructor = null,
    /// Changes whenever the slot is reused, so stale references are detected.
    generation: u32 = 0,
};

/// A protocol object owned by one client.
pub const Resource = struct {
    client: *Client,
    id: u32,

    fn object(self: Resource) ?*Object {
        return self.client.object(self.id);
    }

    pub fn alive(self: Resource) bool {
        return self.object() != null;
    }

    pub fn version(self: Resource) u32 {
        return if (self.object()) |value| value.version else 0;
    }

    pub fn interface(self: Resource) ?*const Interface {
        return if (self.object()) |value| value.interface else null;
    }

    /// Routes this object's requests to `handler` and its destruction to `destructor`.
    pub fn setHandler(self: Resource, data: ?*anyopaque, handler: ?Handler, destructor: ?Destructor) void {
        const value = self.object() orelse return;
        value.data = data;
        value.handler = handler;
        value.destructor = destructor;
    }

    pub fn userData(self: Resource) ?*anyopaque {
        return if (self.object()) |value| value.data else null;
    }

    /// Destroys the object on the server side, as wl_resource_destroy.
    pub fn destroy(self: Resource) void {
        self.client.destroyObject(self.id, true);
    }

    /// Sends wl_display.error for this object and disconnects the client once flushed.
    pub fn postError(self: Resource, code: u32, comptime format: []const u8, args: anytype) void {
        var text: [512]u8 = undefined;
        const message = std.fmt.bufPrint(&text, format, args) catch format;
        self.client.postError(self.id, code, message);
    }

    pub fn send(self: Resource, comptime opcode: u16, comptime message: Message, new_interface: ?*const Interface, args: anytype) Resource {
        return self.client.marshal(self, opcode, message, new_interface, args) catch |err| {
            self.client.fail(err);
            return .{ .client = self.client, .id = 0 };
        };
    }
};

/// One received request while its handler runs; strings and arrays point into it.
pub const Request = struct {
    client: *Client,
    id: u32,
    opcode: u16,
    body: []const u8,
    fds: []const Fd,
    taken: usize = 0,

    fn word(self: *Request, at: *usize) Error!u32 {
        if (at.* + 4 > self.body.len) return error.Protocol;
        defer at.* += 4;
        return std.mem.readInt(u32, self.body[at.*..][0..4], .little);
    }

    fn bytes(self: *Request, at: *usize) Error![]const u8 {
        const len = try self.word(at);
        const padded = std.mem.alignForward(usize, len, 4);
        if (at.* + padded > self.body.len) return error.Protocol;
        defer at.* += padded;
        return self.body[at.*..][0..len];
    }

    fn resource(self: *Request, comptime T: type, id: u32) Error!T {
        if (T == Resource) return .{ .client = self.client, .id = id };
        switch (@typeInfo(T)) {
            .optional => |o| return if (id == 0) null else try self.resource(o.child, id),
            else => {
                // Object arguments must have the interface the protocol names.
                const found = self.client.object(id) orelse return error.Protocol;
                if (found.interface != &T.interface and !std.mem.eql(u8, found.interface.name, T.interface.name)) return error.Protocol;
                return .{ .resource = .{ .client = self.client, .id = id } };
            },
        }
    }

    /// Decodes a request payload struct according to the request's signature.
    pub fn decode(self: *Request, comptime S: type, comptime signature: []const u8) Error!S {
        var result: S = undefined;
        const info = @typeInfo(S).@"struct";
        var at: usize = 0;
        comptime var field = 0;
        comptime var nullable = false;
        inline for (signature) |code| {
            if (code == '?') {
                nullable = true;
                continue;
            }
            const name = info.field_names[field];
            const T = info.field_types[field];
            switch (code) {
                'i' => @field(result, name) = @bitCast(try self.word(&at)),
                'u' => @field(result, name) = try self.word(&at),
                'f' => @field(result, name) = @as(f64, @floatFromInt(@as(i32, @bitCast(try self.word(&at))))) / 256,
                's' => {
                    const value = try self.bytes(&at);
                    if (value.len == 0) {
                        @field(result, name) = if (@typeInfo(T) == .optional) null else "";
                    } else {
                        @field(result, name) = value[0 .. value.len - 1 :0];
                    }
                },
                'a' => @field(result, name) = try self.bytes(&at),
                'o', 'n' => @field(result, name) = try self.resource(T, try self.word(&at)),
                'h' => {
                    if (self.taken >= self.fds.len) return error.Protocol;
                    @field(result, name) = self.fds[self.taken];
                    self.taken += 1;
                },
                else => @compileError("unknown signature code"),
            }
            field += 1;
            nullable = false;
        }
        comptime std.debug.assert(field == info.field_names.len);
        return result;
    }
};

/// Routes typed requests of interface binding `T` to `handler(data, self, request)`.
pub fn Dispatcher(comptime T: type, comptime Data: type, comptime handler: fn (*Data, T, T.Request) void) type {
    return struct {
        pub fn dispatch(data: ?*anyopaque, request: *Request) void {
            const info = @typeInfo(T.Request).@"union";
            inline for (info.field_names, info.field_types, 0..) |name, Payload, opcode| {
                if (request.opcode == opcode) {
                    const payload = request.decode(Payload, T.interface.requests[opcode].signature) catch {
                        request.client.postError(request.id, DisplayError.invalid_method, "invalid arguments");
                        return;
                    };
                    const self: T = .{ .resource = .{ .client = request.client, .id = request.id } };
                    handler(@ptrCast(@alignCast(data)), self, @unionInit(T.Request, name, payload));
                    return;
                }
            }
        }
    };
}

pub fn Finalizer(comptime T: type, comptime Data: type, comptime destructor: fn (*Data, T) void) type {
    return struct {
        pub fn destroy(data: ?*anyopaque, resource: Resource) void {
            destructor(@ptrCast(@alignCast(data)), .{ .resource = resource });
        }
    };
}

// wl_display, wl_registry and wl_callback belong to the runtime itself.
const display_interface: Interface = .{ .name = "wl_display", .version = 1, .requests = &.{
    .{ .name = "sync", .signature = "n", .new_id = struct {
        fn get() *const Interface {
            return &callback_interface;
        }
    }.get },
    .{ .name = "get_registry", .signature = "n", .new_id = struct {
        fn get() *const Interface {
            return &registry_interface;
        }
    }.get },
}, .events = &.{
    .{ .name = "error", .signature = "ous" },
    .{ .name = "delete_id", .signature = "u" },
} };
const registry_interface: Interface = .{ .name = "wl_registry", .version = 1, .requests = &.{
    .{ .name = "bind", .signature = "usun" },
}, .events = &.{
    .{ .name = "global", .signature = "usu" },
    .{ .name = "global_remove", .signature = "u" },
} };
pub const callback_interface: Interface = .{ .name = "wl_callback", .version = 1, .requests = &.{}, .events = &.{
    .{ .name = "done", .signature = "u", .destructor = true },
} };

pub const Global = struct {
    server: *Server,
    name: u32,
    interface: *const Interface,
    version: u32,
    data: ?*anyopaque,
    bind: *const fn (data: ?*anyopaque, resource: Resource) void,
    /// Hides privileged globals from clients that may not use them.
    visible: ?*const fn (data: ?*anyopaque, client: *Client) bool = null,
    removed: bool = false,

    fn visibleTo(self: *const Global, client: *Client) bool {
        return if (self.visible) |check| check(self.data, client) else true;
    }

    /// Announces removal; binds that race with it still succeed until `destroy`.
    pub fn remove(self: *Global) void {
        if (self.removed) return;
        self.removed = true;
        for (self.server.clients.items) |client| {
            if (!self.visibleTo(client)) continue;
            for (client.registries.items) |registry| {
                _ = registry.send(1, registry_interface.events[1], null, .{self.name});
            }
        }
    }

    pub fn destroy(self: *Global) void {
        self.remove();
        const server = self.server;
        for (server.globals.items, 0..) |global, index| if (global == self) {
            _ = server.globals.orderedRemove(index);
            break;
        };
        server.allocator.destroy(self);
    }
};

pub const Client = struct {
    server: *Server,
    fd: Fd,
    objects: std.ArrayList(?Object) = .empty,
    server_objects: std.ArrayList(?Object) = .empty,
    free_server_ids: std.ArrayList(u32) = .empty,
    registries: std.ArrayList(Resource) = .empty,
    in: [4 * max_message]u8 = undefined,
    in_len: usize = 0,
    in_fds: std.ArrayList(Fd) = .empty,
    out: std.ArrayList(u8) = .empty,
    out_fds: std.ArrayList(Fd) = .empty,
    /// Set once the connection must close; it does after pending events are flushed.
    closing: bool = false,
    failure: ?Error = null,
    generation: u32 = 0,
    writable_wait: bool = false,
    pid: i32 = 0,
    uid: u32 = 0,
    /// Compositor state for this client.
    data: ?*anyopaque = null,
    on_destroy: ?*const fn (data: ?*anyopaque, client: *Client) void = null,
    debug: bool = false,

    fn object(self: *Client, id: u32) ?*Object {
        if (id >= server_base) {
            const index = id - server_base;
            if (index >= self.server_objects.items.len) return null;
            return if (self.server_objects.items[index]) |*value| value else null;
        }
        if (id >= self.objects.items.len) return null;
        return if (self.objects.items[id]) |*value| value else null;
    }

    fn fail(self: *Client, err: Error) void {
        if (self.failure == null) self.failure = err;
        self.closing = true;
    }

    /// Registers a client-allocated id; ids must be fresh and allocated in order.
    fn insertClient(self: *Client, id: u32, value: Object) Error!void {
        if (id == 0 or id >= server_base or id > self.objects.items.len) return error.Protocol;
        self.generation +%= 1;
        var stored = value;
        stored.generation = self.generation;
        if (id == self.objects.items.len) {
            try self.objects.append(self.server.allocator, stored);
        } else {
            if (self.objects.items[id] != null) return error.Protocol;
            self.objects.items[id] = stored;
        }
    }

    fn insertServer(self: *Client, value: Object) Error!u32 {
        self.generation +%= 1;
        var stored = value;
        stored.generation = self.generation;
        if (self.free_server_ids.pop()) |index| {
            self.server_objects.items[index] = stored;
            return server_base + index;
        }
        if (self.server_objects.items.len >= 0x00ffffff) return error.OutOfMemory;
        try self.server_objects.append(self.server.allocator, stored);
        return server_base + @as(u32, @intCast(self.server_objects.items.len - 1));
    }

    /// Creates a resource for a client-allocated new_id, as wl_resource_create.
    pub fn createResource(self: *Client, interface: *const Interface, version: u32, id: u32) Error!Resource {
        try self.insertClient(id, .{ .interface = interface, .version = version });
        return .{ .client = self, .id = id };
    }

    fn destroyObject(self: *Client, id: u32, notify: bool) void {
        const value = self.object(id) orelse return;
        const generation = value.generation;
        if (value.destructor) |destructor| destructor(value.data, .{ .client = self, .id = id });
        // The destructor may have destroyed the object itself.
        const current = self.object(id) orelse return;
        if (current.generation != generation) return;
        for (self.registries.items, 0..) |registry, index| if (registry.id == id) {
            _ = self.registries.swapRemove(index);
            break;
        };
        if (id >= server_base) {
            self.server_objects.items[id - server_base] = null;
            self.free_server_ids.append(self.server.allocator, id - server_base) catch {};
        } else {
            self.objects.items[id] = null;
            // The client reuses its id once told the object is gone.
            if (notify and id != 1) _ = (Resource{ .client = self, .id = 1 }).send(1, display_interface.events[1], null, .{id});
        }
    }

    fn postError(self: *Client, id: u32, code: u32, message: []const u8) void {
        if (self.closing) return;
        if (self.debug) std.log.warn("wayland server: error {d} on #{d}: {s}", .{ code, id, message });
        const display: Resource = .{ .client = self, .id = 1 };
        // Send even for objects the server no longer knows, as libwayland does.
        var buffer: [max_message]u8 = undefined;
        var len: usize = 8;
        wire.put(&buffer, &len, id) catch {};
        wire.put(&buffer, &len, code) catch {};
        wire.putString(&buffer, &len, message[0..@min(message.len, 1000)]) catch {};
        self.queue(display.id, 0, buffer[0..len], &.{}) catch {};
        self.closing = true;
    }

    fn queue(self: *Client, id: u32, opcode: u16, frame: []u8, fds: []const Fd) Error!void {
        std.mem.writeInt(u32, frame[0..4], id, .little);
        std.mem.writeInt(u32, frame[4..8], @as(u32, @intCast(frame.len)) << 16 | opcode, .little);
        if (self.out.items.len + frame.len > max_pending) return error.OutOfMemory;
        try self.out.appendSlice(self.server.allocator, frame);
        try self.out_fds.appendSlice(self.server.allocator, fds);
        self.server.dirty = true;
    }

    fn marshal(self: *Client, resource: Resource, comptime opcode: u16, comptime message: Message, new_interface: ?*const Interface, args: anytype) Error!Resource {
        if (self.closing) return error.Disconnected;
        const target = self.object(resource.id) orelse return error.Protocol;
        // Events newer than the bound version must not be sent; callers check `version`.
        if (message.since > target.version) return error.Protocol;
        const target_version = target.version;
        var buffer: [max_message]u8 = undefined;
        var len: usize = 8;
        var fds: [max_fds]Fd = undefined;
        var fd_count: usize = 0;
        errdefer for (fds[0..fd_count]) |fd| {
            _ = std.c.close(fd);
        };
        var created: u32 = 0;
        const fields = @typeInfo(@TypeOf(args)).@"struct".field_names;
        comptime var field = 0;
        inline for (message.signature) |code| {
            if (code == '?') continue;
            const value = @field(args, fields[field]);
            field += 1;
            switch (code) {
                'i' => try wire.put(&buffer, &len, @bitCast(@as(i32, value))),
                'u' => try wire.put(&buffer, &len, @as(u32, value)),
                'f' => try wire.put(&buffer, &len, @bitCast(@as(i32, @intFromFloat(@round(std.math.clamp(@as(f64, value), -8388608, 8388607) * 256))))),
                's' => try wire.putString(&buffer, &len, value),
                'a' => try wire.putArray(&buffer, &len, value),
                'o' => try wire.put(&buffer, &len, resourceId(value)),
                'n' => {
                    if (@TypeOf(value) != wire.NewId) @compileError("new_id arguments take wire.new_id");
                    const interface = new_interface orelse (message.new_id orelse return error.Protocol)();
                    created = try self.insertServer(.{ .interface = interface, .version = target_version });
                    try wire.put(&buffer, &len, created);
                },
                'h' => {
                    if (fd_count == max_fds) return error.Protocol;
                    const copy = std.c.fcntl(value, std.c.F.DUPFD_CLOEXEC, @as(c_int, 0));
                    if (copy < 0) return error.IoFailed;
                    fds[fd_count] = copy;
                    fd_count += 1;
                },
                else => @compileError("unknown signature code"),
            }
        }
        comptime std.debug.assert(field == fields.len);
        if (self.debug) trace("server -> ", target.interface.name, resource.id, message, buffer[8..len]);
        try self.queue(resource.id, opcode, buffer[0..len], fds[0..fd_count]);
        fd_count = 0;
        if (message.destructor) self.destroyObject(resource.id, true);
        return .{ .client = self, .id = created };
    }

    /// Writes queued events; returns false when the socket would block.
    fn flush(self: *Client) bool {
        while (self.out.items.len > 0) {
            var iov = [_]std.posix.iovec_const{.{ .base = self.out.items.ptr, .len = self.out.items.len }};
            var control: [wire.cmsgSpace(max_fds)]u8 align(8) = @splat(0);
            var header: std.c.msghdr_const = .{ .name = null, .namelen = 0, .iov = &iov, .iovlen = 1, .control = null, .controllen = 0, .flags = 0 };
            const fd_count = @min(self.out_fds.items.len, max_fds);
            if (fd_count > 0) {
                wire.writeCmsg(&control, self.out_fds.items[0..fd_count]);
                header.control = &control;
                header.controllen = @intCast(wire.cmsgSpace(fd_count));
            }
            const sent = std.c.sendmsg(self.fd, &header, 0x4000 | 0x40); // MSG_NOSIGNAL | MSG_DONTWAIT
            if (sent < 0) {
                switch (std.c._errno().*) {
                    4 => continue,
                    11 => return false,
                    else => {
                        self.fail(error.IoFailed);
                        self.out.clearRetainingCapacity();
                        return true;
                    },
                }
            }
            for (self.out_fds.items[0..fd_count]) |fd| _ = std.c.close(fd);
            self.out_fds.replaceRange(self.server.allocator, 0, fd_count, &.{}) catch {};
            self.out.replaceRange(self.server.allocator, 0, @intCast(sent), &.{}) catch {};
        }
        return true;
    }

    fn read(self: *Client) Error!bool {
        if (self.in_len == self.in.len) return error.Protocol;
        var iov = [_]std.posix.iovec{.{ .base = self.in[self.in_len..].ptr, .len = self.in.len - self.in_len }};
        var control: [wire.cmsgSpace(max_fds)]u8 align(8) = undefined;
        var header: std.c.msghdr = .{ .name = null, .namelen = 0, .iov = &iov, .iovlen = 1, .control = &control, .controllen = control.len, .flags = 0 };
        const received = while (true) {
            const result = std.c.recvmsg(self.fd, &header, 0x40 | 0x40000000); // MSG_DONTWAIT | MSG_CMSG_CLOEXEC
            if (result >= 0) break result;
            switch (std.c._errno().*) {
                4 => continue,
                11 => return false,
                else => return error.IoFailed,
            }
        };
        var offset: usize = 0;
        const control_len: usize = @intCast(header.controllen);
        while (offset + 16 <= control_len) {
            const len = std.mem.readInt(usize, control[offset..][0..8], .little);
            const level = std.mem.readInt(i32, control[offset + 8 ..][0..4], .little);
            const kind = std.mem.readInt(i32, control[offset + 12 ..][0..4], .little);
            if (len < 16 or offset + len > control_len) break;
            if (level == 1 and kind == 1) {
                var at = offset + 16;
                while (at + 4 <= offset + len) : (at += 4) {
                    const fd = std.mem.readInt(i32, control[at..][0..4], .little);
                    self.in_fds.append(self.server.allocator, fd) catch {
                        _ = std.c.close(fd);
                        return error.OutOfMemory;
                    };
                }
            }
            offset += std.mem.alignForward(usize, len, 8);
        }
        if (header.flags & 0x8 != 0) return error.Protocol; // MSG_CTRUNC
        if (received == 0) return error.Disconnected;
        self.in_len += @intCast(received);
        return true;
    }

    fn dispatchPending(self: *Client) void {
        while (!self.closing and self.in_len >= 8) {
            const id = std.mem.readInt(u32, self.in[0..4], .little);
            const word = std.mem.readInt(u32, self.in[4..8], .little);
            const size: usize = word >> 16;
            if (size < 8 or size > max_message or size % 4 != 0) return self.fail(error.Protocol);
            if (self.in_len < size) break;
            var message: [max_message]u8 = undefined;
            @memcpy(message[0..size], self.in[0..size]);
            std.mem.copyForwards(u8, self.in[0 .. self.in_len - size], self.in[size..self.in_len]);
            self.in_len -= size;
            self.deliver(id, @intCast(word & 0xffff), message[8..size]);
        }
    }

    fn deliver(self: *Client, id: u32, opcode: u16, body: []const u8) void {
        const target = self.object(id) orelse return self.postError(id, DisplayError.invalid_object, "invalid object");
        if (opcode >= target.interface.requests.len) return self.postError(id, DisplayError.invalid_method, "invalid method");
        const message = target.interface.requests[opcode];
        if (message.since > target.version) return self.postError(id, DisplayError.invalid_method, "request newer than the bound version");
        const generation = target.generation;
        const interface = target.interface;
        const version = target.version;
        // Validate the body and register new objects before any handler sees them.
        var fd_count: usize = 0;
        var at: usize = 0;
        var nullable = false;
        for (message.signature) |code| {
            switch (code) {
                '?' => {
                    nullable = true;
                    continue;
                },
                'i', 'u', 'f' => {
                    if (at + 4 > body.len) return self.postError(id, DisplayError.invalid_method, "short message");
                    at += 4;
                },
                's', 'a' => {
                    if (at + 4 > body.len) return self.postError(id, DisplayError.invalid_method, "short message");
                    const len = std.mem.readInt(u32, body[at..][0..4], .little);
                    const padded = std.mem.alignForward(usize, len, 4);
                    if (len > body.len or at + 4 + padded > body.len) return self.postError(id, DisplayError.invalid_method, "short message");
                    if (code == 's') {
                        if (len == 0 and !nullable) return self.postError(id, DisplayError.invalid_method, "null string");
                        if (len > 0 and body[at + 4 + len - 1] != 0) return self.postError(id, DisplayError.invalid_method, "unterminated string");
                    }
                    at += 4 + padded;
                },
                'o' => {
                    if (at + 4 > body.len) return self.postError(id, DisplayError.invalid_method, "short message");
                    const object_id = std.mem.readInt(u32, body[at..][0..4], .little);
                    at += 4;
                    if (object_id == 0 and !nullable) return self.postError(id, DisplayError.invalid_method, "null object");
                    if (object_id != 0 and self.object(object_id) == null) return self.postError(object_id, DisplayError.invalid_object, "unknown object argument");
                },
                'n' => {
                    if (at + 4 > body.len) return self.postError(id, DisplayError.invalid_method, "short message");
                    const created = std.mem.readInt(u32, body[at..][0..4], .little);
                    at += 4;
                    // Untyped new ids (wl_registry.bind) are created by the registry itself.
                    if (message.new_id == null) {
                        if (created == 0 or created >= server_base or created > self.objects.items.len or (created < self.objects.items.len and self.objects.items[created] != null)) return self.postError(id, DisplayError.invalid_object, "invalid new id");
                        continue;
                    }
                    self.insertClient(created, .{ .interface = message.new_id.?(), .version = version }) catch return self.postError(id, DisplayError.invalid_object, "invalid new id");
                },
                'h' => fd_count += 1,
                else => {},
            }
            nullable = false;
        }
        if (at != body.len) return self.postError(id, DisplayError.invalid_method, "trailing bytes");
        if (fd_count > self.in_fds.items.len) return self.postError(id, DisplayError.invalid_method, "missing file descriptor");
        var fds: [max_fds]Fd = undefined;
        const fd_take = @min(fd_count, max_fds);
        @memcpy(fds[0..fd_take], self.in_fds.items[0..fd_take]);
        self.in_fds.replaceRange(self.server.allocator, 0, fd_take, &.{}) catch {};
        if (self.debug) trace("server <- ", interface.name, id, message, body);
        var request: Request = .{ .client = self, .id = id, .opcode = opcode, .body = body, .fds = fds[0..fd_take] };
        const current = self.object(id).?;
        if (current.handler) |handler| handler(current.data, &request);
        // Descriptors the handler did not take are closed.
        for (fds[request.taken..fd_take]) |fd| _ = std.c.close(fd);
        if (message.destructor) {
            if (self.object(id)) |still| if (still.generation == generation) self.destroyObject(id, true);
        }
    }

    /// Releases every object, as when the connection closes.
    fn teardown(self: *Client) void {
        const allocator = self.server.allocator;
        var id = self.objects.items.len;
        while (id > 2) {
            id -= 1;
            self.destroyObject(@intCast(id), false);
        }
        var index = self.server_objects.items.len;
        while (index > 0) {
            index -= 1;
            self.destroyObject(server_base + @as(u32, @intCast(index)), false);
        }
        if (self.on_destroy) |callback| callback(self.data, self);
        for (self.in_fds.items) |fd| _ = std.c.close(fd);
        for (self.out_fds.items) |fd| _ = std.c.close(fd);
        self.in_fds.deinit(allocator);
        self.out_fds.deinit(allocator);
        self.out.deinit(allocator);
        self.objects.deinit(allocator);
        self.server_objects.deinit(allocator);
        self.free_server_ids.deinit(allocator);
        self.registries.deinit(allocator);
        _ = std.c.close(self.fd);
    }

    /// Requests disconnection after pending events are sent.
    pub fn close(self: *Client) void {
        self.closing = true;
        self.server.dirty = true;
    }
};

fn resourceId(value: anytype) u32 {
    const T = @TypeOf(value);
    if (T == Resource) return value.id;
    if (T == @TypeOf(null)) return 0;
    return switch (@typeInfo(T)) {
        .optional => if (value) |inner| resourceId(inner) else 0,
        else => value.resource.id,
    };
}

fn trace(prefix: []const u8, interface: []const u8, id: u32, message: Message, body: []const u8) void {
    var line: [1024]u8 = undefined;
    const text = std.fmt.bufPrint(&line, "{s}{s}#{d}.{s} ({d} bytes)\n", .{ prefix, interface, id, message.name, body.len }) catch return;
    _ = std.c.write(2, text.ptr, text.len);
}

/// An epoll loop for the compositor thread: sockets, timers and other descriptors.
pub const Loop = struct {
    epoll: Fd,
    sources: std.ArrayList(*Source) = .empty,
    allocator: std.mem.Allocator,

    pub const Callback = *const fn (data: ?*anyopaque, events: u32) void;
    pub const Source = struct {
        fd: Fd,
        data: ?*anyopaque,
        callback: Callback,
        owned: bool = false,
        timer: bool = false,
        removed: bool = false,
    };

    pub fn init(allocator: std.mem.Allocator) Error!Loop {
        const fd = linux.epoll_create1(linux.EPOLL.CLOEXEC);
        if (linux.errno(fd) != .SUCCESS) return error.IoFailed;
        return .{ .epoll = @intCast(fd), .allocator = allocator };
    }

    pub fn deinit(self: *Loop) void {
        for (self.sources.items) |source| {
            if (source.owned) _ = std.c.close(source.fd);
            self.allocator.destroy(source);
        }
        self.sources.deinit(self.allocator);
        _ = std.c.close(self.epoll);
    }

    pub fn add(self: *Loop, fd: Fd, events: u32, data: ?*anyopaque, callback: Callback) Error!*Source {
        const source = try self.allocator.create(Source);
        errdefer self.allocator.destroy(source);
        source.* = .{ .fd = fd, .data = data, .callback = callback };
        var event: linux.epoll_event = .{ .events = events, .data = .{ .ptr = @intFromPtr(source) } };
        if (linux.errno(linux.epoll_ctl(self.epoll, linux.EPOLL.CTL_ADD, fd, &event)) != .SUCCESS) return error.IoFailed;
        try self.sources.append(self.allocator, source);
        return source;
    }

    pub fn modify(self: *Loop, source: *Source, events: u32) void {
        var event: linux.epoll_event = .{ .events = events, .data = .{ .ptr = @intFromPtr(source) } };
        _ = linux.epoll_ctl(self.epoll, linux.EPOLL.CTL_MOD, source.fd, &event);
    }

    /// A periodic or one-shot timer; arm it with `arm`.
    pub fn timer(self: *Loop, data: ?*anyopaque, callback: Callback) Error!*Source {
        const fd = linux.timerfd_create(linux.TIMERFD_CLOCK.MONOTONIC, .{ .CLOEXEC = true, .NONBLOCK = true });
        if (linux.errno(fd) != .SUCCESS) return error.IoFailed;
        const source = self.add(@intCast(fd), linux.EPOLL.IN, data, callback) catch |err| {
            _ = std.c.close(@intCast(fd));
            return err;
        };
        source.owned = true;
        source.timer = true;
        return source;
    }

    /// Fires `source` after `ms` milliseconds (0 disarms it).
    pub fn arm(source: *Source, ms: u32) void {
        const spec: linux.itimerspec = .{
            .it_interval = .{ .sec = 0, .nsec = 0 },
            .it_value = .{ .sec = @intCast(ms / 1000), .nsec = @intCast(@as(u64, ms % 1000) * 1_000_000) },
        };
        _ = linux.timerfd_settime(source.fd, .{}, &spec, null);
    }

    pub fn remove(self: *Loop, source: *Source) void {
        _ = linux.epoll_ctl(self.epoll, linux.EPOLL.CTL_DEL, source.fd, null);
        source.removed = true;
        for (self.sources.items, 0..) |candidate, index| if (candidate == source) {
            _ = self.sources.swapRemove(index);
            break;
        };
        if (source.owned) _ = std.c.close(source.fd);
        self.allocator.destroy(source);
    }

    /// Waits up to `timeout_ms` (-1 forever) and runs ready callbacks.
    pub fn iterate(self: *Loop, timeout_ms: i32) void {
        var events: [32]linux.epoll_event = undefined;
        const count = linux.epoll_wait(self.epoll, &events, events.len, timeout_ms);
        if (linux.errno(count) != .SUCCESS) return;
        // Callbacks may remove later sources; check membership before each call.
        for (events[0..count]) |event| {
            const source: *Source = @ptrFromInt(event.data.ptr);
            const live = for (self.sources.items) |candidate| {
                if (candidate == source) break true;
            } else false;
            if (!live) continue;
            if (source.timer) {
                var expirations: u64 = 0;
                _ = linux.read(source.fd, std.mem.asBytes(&expirations), 8);
            }
            source.callback(source.data, event.events);
        }
    }
};

pub const Server = struct {
    allocator: std.mem.Allocator,
    loop: Loop,
    globals: std.ArrayList(*Global) = .empty,
    clients: std.ArrayList(*Client) = .empty,
    next_global: u32 = 1,
    serial: u32 = 0,
    listen_fd: Fd = -1,
    lock_fd: Fd = -1,
    socket_path: [108:0]u8 = @splat(0),
    lock_path: [113:0]u8 = @splat(0),
    socket_name: [32:0]u8 = @splat(0),
    listen_source: ?*Loop.Source = null,
    /// Set when events were queued; `flushClients` sends them.
    dirty: bool = false,
    debug: bool = false,
    /// Called for every new client before it can send requests.
    on_client: ?*const fn (data: ?*anyopaque, client: *Client) void = null,
    on_client_data: ?*anyopaque = null,

    pub fn create(allocator: std.mem.Allocator) Error!*Server {
        const self = try allocator.create(Server);
        errdefer allocator.destroy(self);
        const debug = if (std.c.getenv("WAYLAND_DEBUG")) |value| blk: {
            const text = std.mem.span(value);
            break :blk std.mem.eql(u8, text, "1") or std.mem.indexOf(u8, text, "server") != null;
        } else false;
        self.* = .{ .allocator = allocator, .loop = try Loop.init(allocator), .debug = debug };
        return self;
    }

    pub fn destroy(self: *Server) void {
        while (self.clients.items.len > 0) self.disconnect(self.clients.items[self.clients.items.len - 1]);
        self.clients.deinit(self.allocator);
        for (self.globals.items) |global| self.allocator.destroy(global);
        self.globals.deinit(self.allocator);
        if (self.listen_fd >= 0) {
            _ = std.c.close(self.listen_fd);
            _ = sys.unlink(&self.socket_path);
        }
        if (self.lock_fd >= 0) {
            _ = sys.unlink(&self.lock_path);
            _ = std.c.close(self.lock_fd);
        }
        self.loop.deinit();
        self.allocator.destroy(self);
    }

    pub fn nextSerial(self: *Server) u32 {
        self.serial +%= 1;
        return self.serial;
    }

    pub fn createGlobal(self: *Server, interface: *const Interface, version: u32, data: ?*anyopaque, bind: *const fn (?*anyopaque, Resource) void) Error!*Global {
        const global = try self.allocator.create(Global);
        errdefer self.allocator.destroy(global);
        global.* = .{ .server = self, .name = self.next_global, .interface = interface, .version = version, .data = data, .bind = bind };
        self.next_global += 1;
        try self.globals.append(self.allocator, global);
        for (self.clients.items) |client| {
            if (!global.visibleTo(client)) continue;
            for (client.registries.items) |registry| announce(registry, global);
        }
        return global;
    }

    fn announce(registry: Resource, global: *Global) void {
        _ = registry.send(0, registry_interface.events[0], null, .{ global.name, global.interface.name, global.version });
    }

    /// Listens on the first free wayland-N socket in XDG_RUNTIME_DIR, as wl_display_add_socket_auto.
    pub fn addSocketAuto(self: *Server) Error![:0]const u8 {
        const runtime = std.mem.span(std.c.getenv("XDG_RUNTIME_DIR") orelse return error.IoFailed);
        var index: u32 = 0;
        while (index < 32) : (index += 1) {
            const name = std.fmt.bufPrintSentinel(&self.socket_name, "wayland-{d}", .{index}, 0) catch return error.IoFailed;
            if (self.listenOn(runtime, name)) return name else |_| {}
        }
        return error.IoFailed;
    }

    fn listenOn(self: *Server, runtime: []const u8, name: []const u8) Error!void {
        const lock = std.fmt.bufPrintSentinel(&self.lock_path, "{s}/{s}.lock", .{ runtime, name }, 0) catch return error.IoFailed;
        const lock_fd = sys.open(lock, 0o2 | 0o100 | 0o2000000, @as(c_uint, 0o660)); // O_RDWR | O_CREAT | O_CLOEXEC
        if (lock_fd < 0) return error.IoFailed;
        errdefer _ = std.c.close(lock_fd);
        if (sys.flock(lock_fd, 2 | 4) != 0) return error.IoFailed; // LOCK_EX | LOCK_NB
        const path = std.fmt.bufPrintSentinel(&self.socket_path, "{s}/{s}", .{ runtime, name }, 0) catch return error.IoFailed;
        // A stale socket from a crashed server is removed once its lock is held.
        _ = sys.unlink(path);
        const fd = std.c.socket(1, 1 | 0o2000000 | 0o4000, 0); // AF_UNIX, SOCK_STREAM | CLOEXEC | NONBLOCK
        if (fd < 0) return error.IoFailed;
        errdefer _ = std.c.close(fd);
        var address: wire.SockaddrUn = .{};
        if (path.len >= address.path.len) return error.IoFailed;
        @memcpy(address.path[0..path.len], path);
        if (sys.bind(fd, @ptrCast(&address), @sizeOf(wire.SockaddrUn)) != 0) return error.IoFailed;
        if (sys.listen(fd, 128) != 0) return error.IoFailed;
        self.listen_source = try self.loop.add(fd, linux.EPOLL.IN, self, &acceptReady);
        self.listen_fd = fd;
        self.lock_fd = lock_fd;
    }

    fn acceptReady(data: ?*anyopaque, _: u32) void {
        const self: *Server = @ptrCast(@alignCast(data));
        while (true) {
            const fd = sys.accept4(self.listen_fd, null, null, 0o2000000 | 0o4000);
            if (fd < 0) return;
            _ = self.addClient(fd) catch {
                _ = std.c.close(fd);
            };
        }
    }

    /// Serves an already connected socket, as wl_client_create.
    pub fn addClient(self: *Server, fd: Fd) Error!*Client {
        const client = try self.allocator.create(Client);
        errdefer self.allocator.destroy(client);
        client.* = .{ .server = self, .fd = fd, .debug = self.debug };
        errdefer client.objects.deinit(self.allocator);
        // Id 0 is null; id 1 is the display.
        try client.objects.appendSlice(self.allocator, &.{ null, .{ .interface = &display_interface, .version = 1, .data = client, .handler = &displayRequest } });
        var credentials: extern struct { pid: i32, uid: u32, gid: u32 } = undefined;
        var length: u32 = @sizeOf(@TypeOf(credentials));
        if (sys.getsockopt(fd, 1, 17, @ptrCast(&credentials), &length) == 0) { // SOL_SOCKET, SO_PEERCRED
            client.pid = credentials.pid;
            client.uid = credentials.uid;
        }
        const source = try self.loop.add(fd, linux.EPOLL.IN | linux.EPOLL.RDHUP, client, &clientReady);
        errdefer self.loop.remove(source);
        try self.clients.append(self.allocator, client);
        if (self.on_client) |callback| callback(self.on_client_data, client);
        return client;
    }

    fn clientReady(data: ?*anyopaque, events: u32) void {
        const client: *Client = @ptrCast(@alignCast(data));
        if (events & linux.EPOLL.OUT != 0) {
            client.writable_wait = false;
            client.server.dirty = true;
        }
        if (events & linux.EPOLL.IN != 0) {
            while (!client.closing) {
                const more = client.read() catch |err| {
                    client.fail(err);
                    break;
                };
                if (!more) break;
                client.dispatchPending();
            }
        } else if (events & (linux.EPOLL.HUP | linux.EPOLL.ERR | linux.EPOLL.RDHUP) != 0) {
            client.fail(error.Disconnected);
        }
        client.server.dirty = true;
    }

    fn sourceFor(self: *Server, client: *Client) ?*Loop.Source {
        for (self.loop.sources.items) |source| if (source.data == @as(?*anyopaque, client) and source.callback == &clientReady) return source;
        return null;
    }

    fn disconnect(self: *Server, client: *Client) void {
        if (self.sourceFor(client)) |source| self.loop.remove(source);
        for (self.clients.items, 0..) |candidate, index| if (candidate == client) {
            _ = self.clients.orderedRemove(index);
            break;
        };
        client.teardown();
        self.allocator.destroy(client);
    }

    /// Sends queued events and closes clients that failed or were told to close.
    pub fn flushClients(self: *Server) void {
        self.dirty = false;
        var index: usize = 0;
        while (index < self.clients.items.len) {
            const client = self.clients.items[index];
            const done = client.flush();
            if (!done and !client.writable_wait) {
                client.writable_wait = true;
                if (self.sourceFor(client)) |source| self.loop.modify(source, linux.EPOLL.IN | linux.EPOLL.OUT | linux.EPOLL.RDHUP);
            } else if (done and client.writable_wait) {
                client.writable_wait = false;
                if (self.sourceFor(client)) |source| self.loop.modify(source, linux.EPOLL.IN | linux.EPOLL.RDHUP);
            }
            if (client.closing and (done or client.failure != null)) {
                self.disconnect(client);
                continue;
            }
            index += 1;
        }
    }

    /// Runs one loop iteration and flushes events it produced.
    pub fn dispatch(self: *Server, timeout_ms: i32) void {
        self.loop.iterate(timeout_ms);
        self.flushClients();
    }

    fn displayRequest(data: ?*anyopaque, request: *Request) void {
        const client: *Client = @ptrCast(@alignCast(data));
        const created = std.mem.readInt(u32, request.body[0..4], .little);
        const callback: Resource = .{ .client = client, .id = created };
        switch (request.opcode) {
            0 => _ = callback.send(0, callback_interface.events[0], null, .{client.server.serial}),
            1 => {
                const registry = callback;
                registry.setHandler(client, &registryRequest, &registryGone);
                client.registries.append(client.server.allocator, registry) catch return client.fail(error.OutOfMemory);
                for (client.server.globals.items) |global| {
                    if (!global.removed and global.visibleTo(client)) announce(registry, global);
                }
            },
            else => {},
        }
    }

    fn registryGone(data: ?*anyopaque, resource: Resource) void {
        const client: *Client = @ptrCast(@alignCast(data));
        for (client.registries.items, 0..) |registry, index| if (registry.id == resource.id) {
            _ = client.registries.swapRemove(index);
            break;
        };
    }

    fn registryRequest(data: ?*anyopaque, request: *Request) void {
        const client: *Client = @ptrCast(@alignCast(data));
        const payload = request.decode(struct { name: u32, interface: [:0]const u8, version: u32, id: u32 }, "usuu") catch
            return client.postError(request.id, DisplayError.invalid_method, "invalid bind");
        const global = for (client.server.globals.items) |candidate| {
            if (candidate.name == payload.name and candidate.visibleTo(client)) break candidate;
        } else return client.postError(request.id, 0, "invalid global");
        if (!std.mem.eql(u8, payload.interface, global.interface.name))
            return client.postError(request.id, 0, "invalid interface for global");
        if (payload.version == 0 or payload.version > global.version)
            return client.postError(request.id, 0, "invalid version for global");
        const resource = client.createResource(global.interface, payload.version, payload.id) catch
            return client.postError(request.id, DisplayError.invalid_object, "invalid new id");
        global.bind(global.data, resource);
    }
};

// ------------------------------------------------------------------ Tests

const test_thing: Interface = .{ .name = "t_thing", .version = 2, .requests = &.{
    .{ .name = "poke", .signature = "u?s" },
    .{ .name = "make", .signature = "n", .new_id = struct {
        fn get() *const Interface {
            return &test_thing;
        }
    }.get },
    .{ .name = "destroy", .signature = "", .destructor = true },
}, .events = &.{
    .{ .name = "poked", .signature = "us" },
} };

const Thing = struct {
    resource: Resource,
    pub const interface = test_thing;
    pub const Request = union(enum) {
        poke: struct { value: u32, label: ?[:0]const u8 },
        make: struct { id: Thing },
        destroy: struct {},
    };
};

test "server runtime binds globals, dispatches typed requests and recycles destroyed ids" {
    const a = std.testing.allocator;
    const server = try Server.create(a);
    defer server.destroy();
    const State = struct {
        pokes: u32 = 0,
        made: u32 = 0,
        destroyed: u32 = 0,
        last_label: [16]u8 = @splat(0),
        fn bind(data: ?*anyopaque, resource: Resource) void {
            const self: *@This() = @ptrCast(@alignCast(data));
            resource.setHandler(self, &Dispatcher(Thing, @This(), handle).dispatch, &Finalizer(Thing, @This(), gone).destroy);
        }
        fn handle(self: *@This(), thing: Thing, request: Thing.Request) void {
            switch (request) {
                .poke => |args| {
                    self.pokes += args.value;
                    if (args.label) |label| @memcpy(self.last_label[0..label.len], label);
                    _ = thing.resource.send(0, test_thing.events[0], null, .{ args.value * 2, "ok" });
                },
                .make => |args| {
                    self.made += 1;
                    args.id.resource.setHandler(self, &Dispatcher(Thing, @This(), handle).dispatch, &Finalizer(Thing, @This(), gone).destroy);
                },
                .destroy => {},
            }
        }
        fn gone(self: *@This(), _: Thing) void {
            self.destroyed += 1;
        }
    };
    var state: State = .{};
    _ = try server.createGlobal(&test_thing, 2, &state, &State.bind);

    var fds: [2]Fd = undefined;
    try std.testing.expectEqual(@as(c_int, 0), socketpair(1, 1 | 0o2000000, 0, &fds));
    _ = try server.addClient(fds[0]);
    defer _ = std.c.close(fds[1]);

    // A raw client: get_registry(2), bind(name 1, "t_thing", 2, id 3), poke, make(4), destroy 4.
    var request: [256]u8 = undefined;
    var len: usize = 0;
    const Writer = struct {
        fn message(buffer: []u8, at: *usize, id: u32, opcode: u16, words: []const u32, text: ?[]const u8) void {
            const start = at.*;
            at.* += 8;
            for (words) |value| {
                std.mem.writeInt(u32, buffer[at.*..][0..4], value, .little);
                at.* += 4;
            }
            if (text) |value| {
                std.mem.writeInt(u32, buffer[at.*..][0..4], @intCast(value.len + 1), .little);
                at.* += 4;
                const padded = std.mem.alignForward(usize, value.len + 1, 4);
                @memset(buffer[at.*..][0..padded], 0);
                @memcpy(buffer[at.*..][0..value.len], value);
                at.* += padded;
            }
            std.mem.writeInt(u32, buffer[start..][0..4], id, .little);
            std.mem.writeInt(u32, buffer[start + 4 ..][0..4], @as(u32, @intCast(at.* - start)) << 16 | opcode, .little);
        }
    };
    Writer.message(&request, &len, 1, 1, &.{2}, null);
    // bind: name, interface string, version, id
    {
        const start = len;
        len += 8;
        std.mem.writeInt(u32, request[len..][0..4], 1, .little);
        len += 4;
        std.mem.writeInt(u32, request[len..][0..4], 8, .little);
        len += 4;
        @memcpy(request[len..][0..8], "t_thing\x00");
        len += 8;
        std.mem.writeInt(u32, request[len..][0..4], 2, .little);
        len += 4;
        std.mem.writeInt(u32, request[len..][0..4], 3, .little);
        len += 4;
        std.mem.writeInt(u32, request[start..][0..4], 2, .little);
        std.mem.writeInt(u32, request[start + 4 ..][0..4], @as(u32, @intCast(len - start)) << 16 | 0, .little);
    }
    Writer.message(&request, &len, 3, 0, &.{21}, "hi");
    Writer.message(&request, &len, 3, 1, &.{4}, null);
    Writer.message(&request, &len, 4, 2, &.{}, null);
    try std.testing.expectEqual(@as(isize, @intCast(len)), std.c.write(fds[1], &request, len));
    server.dispatch(100);
    try std.testing.expectEqual(@as(u32, 21), state.pokes);
    try std.testing.expectEqualStrings("hi", std.mem.sliceTo(&state.last_label, 0));
    try std.testing.expectEqual(@as(u32, 1), state.made);
    try std.testing.expectEqual(@as(u32, 1), state.destroyed);

    // Events: global(1, "t_thing", 2), poked(42, "ok"), delete_id(4).
    var reply: [512]u8 = undefined;
    const got = std.c.read(fds[1], &reply, reply.len);
    try std.testing.expect(got > 0);
    var at: usize = 0;
    var seen: [3][2]u32 = undefined;
    var count: usize = 0;
    while (at + 8 <= @as(usize, @intCast(got))) {
        const id = std.mem.readInt(u32, reply[at..][0..4], .little);
        const word = std.mem.readInt(u32, reply[at + 4 ..][0..4], .little);
        if (count < seen.len) seen[count] = .{ id, word & 0xffff };
        count += 1;
        at += word >> 16;
    }
    try std.testing.expectEqual(@as(usize, 3), count);
    try std.testing.expectEqual([2]u32{ 2, 0 }, seen[0]);
    try std.testing.expectEqual([2]u32{ 3, 0 }, seen[1]);
    try std.testing.expectEqual([2]u32{ 1, 1 }, seen[2]);

    // A request on an unknown object is a protocol error that closes the client.
    len = 0;
    Writer.message(&request, &len, 9, 0, &.{1}, null);
    _ = std.c.write(fds[1], &request, len);
    server.dispatch(100);
    try std.testing.expectEqual(@as(usize, 0), server.clients.items.len);
}

extern "c" fn socketpair(domain: c_int, kind: c_int, protocol: c_int, fds: *[2]Fd) c_int;
const sys = struct {
    extern "c" fn bind(fd: Fd, address: *const anyopaque, length: u32) c_int;
    extern "c" fn listen(fd: Fd, backlog: c_int) c_int;
    extern "c" fn accept4(fd: Fd, address: ?*anyopaque, length: ?*u32, flags: c_int) Fd;
    extern "c" fn flock(fd: Fd, operation: c_int) c_int;
    extern "c" fn unlink(path: [*:0]const u8) c_int;
    extern "c" fn getsockopt(fd: Fd, level: c_int, name: c_int, value: *anyopaque, length: *u32) c_int;
    extern "c" fn open(path: [*:0]const u8, flags: c_int, ...) Fd;
};
